/**
 *
 * SplitterHandle is a component that displays a handle.
 *
 * [Live Demo](https://www.primereact.org/splitter/)
 *
 * @module SplitterHandle
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { SplitterRootInstance } from './SplitterRoot.types';
/**
 * Defines passthrough(pt) options type in SplitterHandle component.
 */
export type SplitterHandlePassThroughType<E> = PassThroughType<SplitterHandleInstance, E>;
/**
 * Defines passthrough(pt) options of SplitterHandle component.
 */
export interface SplitterHandlePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SplitterHandlePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SplitterHandle component.
 */
export interface SplitterHandleProps extends BaseComponentProps<SplitterHandleInstance, unknown, SplitterHandlePassThrough> {
}
/**
 * Defines valid state in SplitterHandle component.
 */
export interface SplitterHandleState {
}
/**
 * Defines the methods and properties exposed by SplitterHandle component.
 */
export interface SplitterHandleExposes {
    /**
     * The Splitter component instance.
     */
    splitter: SplitterRootInstance | undefined | null;
}
/**
 * Instance of SplitterHandle component.
 */
export type SplitterHandleInstance = ComponentInstance<SplitterHandleProps, SplitterHandleState, SplitterHandleExposes>;
